(function(){
function collect(level, p, tag){
  var LE = Java.loadClass('net.minecraft.world.entity.LivingEntity');
  var box = p.getBoundingBox().inflate(48);
  var list = level.getEntitiesOfClass(LE, box);
  var out = [];
  for (var i = 0; i < list.size(); i++) { var e = list.get(i); if (e.getTags().contains(tag)) { out.push(e); } }
  return out;
}
function fireCount(){
  var txt = AutoJS.read('logs/latest.log');
  var lines = txt.split('\n');
  var n = 0;
  for (var i = 0; i < lines.length; i++) { var L = lines[i]; if (L.indexOf('AP_EVENT_FIRE: id=') >= 0 && L.indexOf('src=INVESTIGATION_KILL') >= 0) { n++; } }
  return n;
}
  var SH = Java.loadClass('net.neoforged.neoforge.server.ServerLifecycleHooks');
  var server = SH.getCurrentServer();
  if (server === null) { return { ok:false, reason:'no-server' }; }
  var ps = server.getPlayerList().getPlayers();
  if (ps.isEmpty()) { return { ok:false, reason:'no-player' }; }
  var p = ps.get(0);
  var MA = Java.loadClass('com.merlinkitsune.astral_dice.component.ModAttachments');
  return { ok:true, fire:fireCount(), player:String(p.getGameProfile().getName()), stage:MA.getInvestigationStage(p) };
})()

