}
function fireCount(){
  var txt = AutoJS.read('logs/latest.log');
  var lines = txt.split('\n');
  var n = 0;
  for (var i = 0; i < lines.length; i++) { var L = lines[i]; if (L.indexOf('AP_EVENT_FIRE: id=') >= 0 && L.indexOf('src=INVESTIGATION_KILL') >= 0) { n++; } }
  return n;
}
  var SH = Java.loadClass('net.neoforged.neoforge.server.ServerLifecycleHooks');
  var server = SH.getCurrentServer();
  var p = server.getPlayerList().getPlayers().get(0);
  var level = p.level;
  var old = collect(level, p, 'IA_TGT');
  for (var i = 0; i < old.length; i++) { old[i].discard(); }
  var ET = Java.loadClass('net.minecraft.world.entity.EntityType');
  var ent = ET.PILLAGER.create(level);
  if (ent === null) { return { ok:false, reason:'spawn-null' }; }
  ent.setPos(p.getX() + 2.5, p.getY(), p.getZ() + 0.5);
  ent.setNoAi(true);
  ent.addTag('IA_TGT');
  level.addFreshEntity(ent);
  ent.setHealth(2.0);
  var ME = Java.loadClass('com.merlinkitsune.astral_dice.effect.ModEffects');
  var MEI = Java.loadClass('net.minecraft.world.effect.MobEffectInstance');
  var eff = ME.UNDERCOVER_INVESTIGATION.get();
  ent.addEffect(new MEI(eff, 1200, 0, false, false, true));
  var MA = Java.loadClass('com.merlinkitsune.astral_dice.component.ModAttachments');
  var Opt = Java.loadClass('java.util.Optional');
  MA.setUndercoverSource(ent, Opt.of(p.uuid));
  MA.setInvestigationStage(p, 1);
  var MM = Java.loadClass('com.merlinkitsune.astral_dice.item.MarkManager');
  MM.apply(ent);
  var marks = MM.apply(ent);
  return { ok:true, hp_before:ent.getHealth(), marks:marks, has_effect:ent.hasEffect(eff),
           stage:MA.getInvestigationStage(p), alive_before:ent.isDeadOrDying() };
})()

